style.css:
@-moz-document domain("discord.com"), domain("discordapp.com") {
:root {
    --hacker-scrollbar: linear-gradient(45deg, #0b6e32 0%, #00ed61 50%, #a8ffca 100%);
    --hacker-font: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace;
    --hacker-panel-opacity: 0.47;
    --hacker-panel: rgba(3, 33, 17, var(--hacker-panel-opacity));
    --hacker-popup: rgba(2, 23, 11, 0.97);
    --hacker-text: #d9ffe6;
    --hacker-muted: #9ee5b6;
    --hacker-border: rgba(28, 240, 102, 0.36);
    --hacker-hover: rgba(16, 104, 45, 0.47);
    --hacker-selected: rgba(10, 115, 43, 0.61);
  }

  /* Keep the Hacker Green palette in either Discord appearance mode. */
  .theme-dark, .theme-light {
    --hacker-panel: rgba(3, 33, 17, var(--hacker-panel-opacity));
    --hacker-popup: rgba(2, 23, 11, 0.97);
    --hacker-text: #d9ffe6;
    --hacker-muted: #9ee5b6;
    --hacker-border: rgba(28, 240, 102, 0.36);
    --hacker-hover: rgba(16, 104, 45, 0.47);
    --hacker-selected: rgba(10, 115, 43, 0.61);
    --font-primary: var(--hacker-font) !important;
    --font-display: var(--hacker-font) !important;
    --font-code: var(--hacker-font) !important;
    --text-default: #d9ffe6 !important;
    --text-link: #7fffac !important;
    --text-brand: #00ff66 !important;
    --brand-500: #00e85c !important;
    --brand-560: #00c84c !important;
    --brand-600: #00a943 !important;
    --brand-experiment: #00e85c !important;
    --button-filled-brand-text: #001b09 !important;
    --button-filled-brand-background: #00e85c !important;
    --button-filled-brand-background-hover: #38ff87 !important;
    color-scheme: dark !important;
  }

  .theme-dark, .theme-light {
    --background-base-lowest: transparent !important;
    --background-base-lower: transparent !important;
    --background-base-low: transparent !important;
    --background-primary: transparent !important;
    --background-secondary: transparent !important;
    --background-secondary-alt: transparent !important;
    --background-tertiary: transparent !important;
    --bg-base-primary: transparent !important;
    --bg-base-secondary: transparent !important;
    --bg-base-tertiary: transparent !important;
    --background-surface-high: var(--hacker-panel) !important;
    --background-surface-higher: var(--hacker-popup) !important;
    --background-surface-highest: var(--hacker-popup) !important;
    --background-floating: var(--hacker-popup) !important;
    --background-modifier-hover: var(--hacker-hover) !important;
    --background-modifier-active: var(--hacker-selected) !important;
    --background-modifier-selected: var(--hacker-selected) !important;
    --background-modifier-accent: var(--hacker-border) !important;
    --channeltextarea-background: var(--hacker-panel) !important;
    --chat-background-default: transparent !important;
    --chat-background: transparent !important;
    --text-normal: var(--hacker-text) !important;
    --text-primary: var(--hacker-text) !important;
    --text-secondary: var(--hacker-muted) !important;
    --text-muted: var(--hacker-muted) !important;
    --header-primary: var(--hacker-text) !important;
    --header-secondary: var(--hacker-muted) !important;
    --channels-default: var(--hacker-muted) !important;
    --interactive-normal: var(--hacker-muted) !important;
    --interactive-hover: var(--hacker-text) !important;
    --interactive-active: var(--hacker-text) !important;
    --input-background: var(--hacker-panel) !important;
    --border-subtle: var(--hacker-border) !important;
    --border-normal: var(--hacker-border) !important;
  }

  /* Exact charcoal grid and scanline settings from ChatGPT Hacker Green. */
  html {
    min-height: 100%;
    background-color: #0a0a0a !important;
    background-image:
      linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
      repeating-linear-gradient(to bottom,
        rgba(10,10,10,0) 0px, rgba(10,10,10,0) 3px,
        rgba(105,255,153,.035) 3px, rgba(105,255,153,.035) 4px) !important;
    background-size: 40px 40px, 40px 40px, 100% 4px !important;
    background-position: 0 0 !important;
    background-repeat: repeat !important;
    background-attachment: fixed !important;
  }
  body {
    min-height: 100vh;
    background: transparent !important;
  }
  #app-mount,
  #app-mount > [class*="app_"],
  #app-mount [class*="appAsidePanelWrapper_"],
  #app-mount [class*="base_"],
  #app-mount [class*="bg_"],
  #app-mount [class*="sidebar_"],
  #app-mount [class*="sidebarList_"],
  #app-mount [class*="chatContent_"],
  #app-mount [class*="messagesWrapper_"],
  #app-mount [class*="membersWrap_"],
  #app-mount [class*="scrollerBase_"] {
    background: transparent !important;
  }

  /* Major columns receive their own translucent surface. Nested scrolling
     wrappers remain clear so repeated glass layers do not hide the gradient. */
  #app-mount [class*="guilds_"],
  #app-mount [class*="sidebarList_"] > [class*="container_"],
  #app-mount [class*="privateChannels_"],
  #app-mount [class*="chat_"],
  #app-mount [class*="members_"],
  #app-mount [class*="container_"][class*="themed_"] {
    background: var(--hacker-panel) !important;
    border-color: var(--hacker-border) !important;
  }
  #app-mount [class*="guilds_"] [class*="scroller_"],
  #app-mount [class*="sidebarList_"] [class*="scroller_"],
  #app-mount [class*="privateChannels_"] [class*="scroller_"],
  #app-mount [class*="members_"] > div,
  #app-mount [class*="member_"],
  #app-mount [class*="chat_"] [class*="content_"] {
    background-color: transparent !important;
  }

  /* Account controls and composer. */
  #app-mount [class*="panels_"],
  #app-mount [class*="channelTextArea_"],
  #app-mount [class*="searchBar_"] {
    background: var(--hacker-panel) !important;
    border: 1px solid var(--hacker-border) !important;
  }
  #app-mount [class*="channelTextArea_"] [class*="scrollableContainer_"],
  #app-mount [class*="form_"],
  #app-mount [class*="typing_"] {
    background: transparent !important;
  }
  #app-mount [class*="form_"]::before,
  #app-mount [class*="form_"]::after,
  #app-mount [class*="sidebar_"]::after {
    background: none !important;
  }

  /* Floating surfaces stay darker for readable menus over the grid background. */
  #app-mount [role="menu"],
  #app-mount [role="listbox"],
  #app-mount [role="dialog"],
  #app-mount [class*="tooltip_"],
  #app-mount [class*="messagesPopoutWrap_"],
  #app-mount [class*="recentMentionsPopout_"],
  #app-mount [class*="userProfileOuter_"],
  #app-mount [class*="emojiPicker_"],
  #app-mount [class*="expressionPickerPositionLayer_"],
  #app-mount [class*="autocomplete_"],
  #app-mount [class*="searchResultsWrap_"] {
    background: var(--hacker-popup) !important;
    color: var(--hacker-text) !important;
    border: 1px solid var(--hacker-border) !important;
    box-shadow: 0 10px 32px rgba(0, 0, 0, 0.3) !important;
  }
  #app-mount [class*="standardSidebarView_"] {
    background: var(--hacker-popup) !important;
  }
  #app-mount [class*="sidebarRegionScroller_"],
  #app-mount [class*="contentRegion_"],
  #app-mount [class*="contentRegionScroller_"] {
    background: transparent !important;
  }

  /* Subtle selections preserve avatars, attachments and status colors. */
  #app-mount [class*="member_"]:hover,
  #app-mount [class*="interactive_"]:hover,
  #app-mount [class*="modeSelected_"] [class*="link_"],
  #app-mount [class*="message_"]:hover {
    background-color: var(--hacker-hover) !important;
  }
  #app-mount [class*="messageContent_"] {
    color: var(--hacker-text) !important;
  }
  #app-mount [class*="messageContent_"] pre,
  #app-mount [class*="messageContent_"] code {
    background: var(--hacker-panel) !important;
    border-color: var(--hacker-border) !important;
  }
  #app-mount a:focus-visible,
  #app-mount button:focus-visible,
  #app-mount [tabindex="0"]:focus-visible {
    outline: 2px solid #00ff66 !important;
    outline-offset: 2px;
  }
  #app-mount [class*="homeIcon_"] {
    color: #00ff66 !important;
    filter: drop-shadow(0 0 4px #00ff66) drop-shadow(0 0 8px rgba(0,255,102,.65));
  }
  #app-mount * {
    /* Chromium must use auto here so native scrollbar colors do not
       override the gradient pseudo-elements below. */
    scrollbar-width: auto !important;
    scrollbar-color: auto !important;
  }
  #app-mount ::-webkit-scrollbar {
    width: 10px !important;
    height: 10px !important;
  }
  #app-mount ::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.15) !important;
  }
  #app-mount ::-webkit-scrollbar-thumb {
    background: var(--hacker-scrollbar) !important;
    border: 2px solid transparent !important;
    background-clip: padding-box !important;
    border-radius: 10px !important;
    min-height: 32px;
    min-width: 32px;
  }

  /* Friends list: match the left sidebar's translucent panel.
     data-list-id is taken from the supplied Friends list markup. */
  #app-mount [data-list-id="people"][class*="peopleList_"] {
    background: var(--hacker-panel) !important;
    box-shadow: inset 0 0 0 1px var(--hacker-border) !important;
  }

  /* Friends side panel: outer container from the supplied markup.
     One tinted surface covers both its header and its scrolling list. */
  #app-mount .container_b17982 {
    background: var(--hacker-panel) !important;
    box-shadow: inset 0 0 0 1px var(--hacker-border) !important;
  }
  #app-mount .container_b17982 > .body_b17982,
  #app-mount .container_b17982 > .header_b5f5a6,
  #app-mount .container_b17982 [data-list-id="friends-list"],
  #app-mount .container_b17982 [data-list-id="friends-list"] > [role="list"] {
    background: transparent !important;
  }
  #app-mount ::-webkit-scrollbar-thumb:hover {
    box-shadow: inset 0 0 0 20px rgba(168, 255, 202, 0.15) !important;
  }
  #app-mount ::-webkit-scrollbar-corner {
    background: transparent !important;
  }

  /* Terminal typography via Discord tokens and native form controls. */
  html, body, #app-mount,
  #app-mount button, #app-mount input, #app-mount textarea,
  #app-mount select, #app-mount [contenteditable="true"] {
    font-family: var(--hacker-font) !important;
    font-variant-ligatures: none !important;
  }
  #app-mount { color: var(--hacker-text) !important; }
  #app-mount ::selection {
    background: rgba(0,255,102,.35) !important;
    color: #f5fff7 !important;
  }
  #app-mount [class*="guilds_"],
  #app-mount [class*="sidebarList_"] > [class*="container_"],
  #app-mount [class*="privateChannels_"],
  #app-mount [class*="chat_"],
  #app-mount [class*="members_"] {
    box-shadow: inset 0 0 0 1px rgba(32,243,107,.18) !important;
  }
  #app-mount [class*="actionButton_"],
  #app-mount [class*="modeSelectButton_"],
  #app-mount [class*="reaction_"] {
    background-color: rgba(4, 57, 26, 0.88) !important;
    color: #d9ffe6 !important;
    border-color: var(--hacker-border) !important;
  }

  /* Side-column palette sampled from the supplied ChatGPT sidebar.
     At 75% opacity this tint reads as approximately #051a10 over #0a0a0a. */
#app-mount [class*="guilds_"],
  #app-mount [class*="sidebarList_"],
  #app-mount [class*="privateChannels_"],
  #app-mount [class*="members_"],
  #app-mount .container_b17982 {
    --hacker-text: #00ff66 !important;
    --hacker-muted: #79ffaa !important;
    --text-default: #00ff66 !important;
    --text-normal: #00ff66 !important;
    --text-primary: #00ff66 !important;
    --text-secondary: #79ffaa !important;
    --text-muted: #79ffaa !important;
    --header-primary: #79ffaa !important;
    --header-secondary: #79ffaa !important;
    --channels-default: #00ff66 !important;
    --interactive-normal: #00ff66 !important;
    --interactive-hover: #b7ffce !important;
    --interactive-active: #b7ffce !important;
    --background-modifier-hover: rgba(12, 91, 39, 0.42) !important;
    --background-modifier-selected: rgba(14, 92, 43, 0.52) !important;
    color: #00ff66 !important;
  }
  #app-mount [class*="guilds_"],
  #app-mount [class*="sidebarList_"] > [class*="container_"],
  #app-mount [class*="privateChannels_"],
  #app-mount [class*="members_"],
  #app-mount .container_b17982 {
    background: rgba(3, 31, 18, 0.75) !important;
    box-shadow: inset 0 0 0 1px rgba(32,243,107,.24) !important;
  }
  #app-mount [class*="sidebarList_"] [class*="name_"],
  #app-mount [class*="sidebarList_"] [class*="username_"],
  #app-mount [class*="sidebarList_"] [class*="channelName_"],
  #app-mount [class*="privateChannels_"] [class*="name_"],
  #app-mount [class*="privateChannels_"] [class*="username_"],
  #app-mount [class*="privateChannels_"] [class*="channelName_"],
  #app-mount [class*="members_"] [class*="name_"],
  #app-mount [class*="members_"] [class*="username_"],
  #app-mount [class*="members_"] [class*="channelName_"],
  #app-mount .container_b17982 [class*="name_"],
  #app-mount .container_b17982 [class*="username_"],
  #app-mount .container_b17982 [class*="channelName_"] {
    color: #00ff66 !important;
  }
  #app-mount [class*="membersGroup_"],
  #app-mount .container_b17982 .header_b5f5a6,
  #app-mount .container_b17982 [class*="header__1af21"] {
    color: #79ffaa !important;
  }
}
